// Package refdata holds the dated reference lists the TLS evaluation judges
// against: the Mozilla and Chrome root stores (with their distrust
// constraints), the published Diffie-Hellman groups, the CT log list and the
// certificate-lifetime limits.
//
// Every list except the lifetime table is generated by ./gen from a downloaded
// source and carries that source's URL, retrieval date and SHA-256. Nothing is
// fetched at run time. The lifetime table is a short schedule transcribed from
// a ballot; it is written by hand in lifetime.go and pinned by a test.
//
// Regenerate (the sources are not committed; licences and attribution are in
// docs/reference-data.md):
//
//	curl -o mozilla.csv 'https://ccadb.my.salesforce-sites.com/ccadb/Report?Name=MozillaTLSServerAuthenticationCSV'
//	curl -o chrome.csv  'https://ccadb.my.salesforce-sites.com/ccadb/Report?Name=ChromeTLSServerAuthenticationCSV'
//	curl -o ct.json     https://www.gstatic.com/ct/log_list/v3/log_list.json
//	for n in 2409 3526 5114 7919; do curl -o rfc$n.txt https://www.rfc-editor.org/rfc/rfc$n.txt; done
//	go run ./internal/refdata/gen -mozilla mozilla.csv -chrome chrome.csv -ctlogs ct.json \
//	    -rfcs . -retrieved YYYY-MM-DD -out internal/refdata
package refdata

import (
	"encoding/base64"
	"sync"
	"time"

	"github.com/example/cipherhorizon/internal/pki"
)

// Source describes where a bundled list came from.
type Source struct {
	Name      string `json:"name"`
	URL       string `json:"source"`
	Retrieved string `json:"retrieved"` // YYYY-MM-DD
	SHA256    string `json:"sha256"`    // of the downloaded source file(s)
	Licence   string `json:"licence"`
	Count     int    `json:"count"`
}

// Age is how old the list is at now, in whole days.
func (s Source) Age(now time.Time) int {
	t, err := time.Parse("2006-01-02", s.Retrieved)
	if err != nil {
		return 0
	}
	return int(now.Sub(t).Hours() / 24)
}

// StaleAfterDays is the age at which a list is flagged as old (REQ-TDAT-3).
const StaleAfterDays = 180

const (
	licenceCCADB  = "CCADB Data Usage Terms (CDLA-Permissive-2.0); attribution: Common CA Database (CCADB)"
	licenceCTList = "Published by Google for CT clients and shipped in Chromium (BSD-3-Clause); factual list"
	licenceRFC    = "Values published in IETF RFCs (IETF Trust legal provisions); factual values"
)

type rootEntry struct {
	SHA256, Name, Owner string
	DistrustAfter       string // YYYY-MM-DD
	SCTNotAfter         int64  // unix seconds
	PermittedDNS        []string
}

// CTLog is one log from the CT log list.
type CTLog struct {
	ID       string // base64 log ID (SHA-256 of the log key)
	Name     string
	Operator string
	State    string
	URL      string
}

// DHPrime is one published Diffie-Hellman group.
type DHPrime struct {
	SHA256     string // of the prime's big-endian bytes, leading zeros trimmed
	Name       string
	Bits       int
	Source     string // "RFC 7919 §A.1"
	Negotiated bool   // an RFC 7919 named group (the recommended kind)
}

var (
	storesOnce      sync.Once
	mozilla, chrome *pki.Store
)

func buildStore(name string, src Source, entries []rootEntry) *pki.Store {
	roots := make([]pki.Root, 0, len(entries))
	for _, e := range entries {
		der, err := base64.StdEncoding.DecodeString(rootDER[e.SHA256])
		if err != nil {
			panic("refdata: root " + e.SHA256 + ": " + err.Error())
		}
		r := pki.Root{SHA256: e.SHA256, DER: der, PermittedDNS: e.PermittedDNS}
		if e.DistrustAfter != "" {
			t, err := time.Parse("2006-01-02", e.DistrustAfter)
			if err != nil {
				panic("refdata: root " + e.SHA256 + ": " + err.Error())
			}
			// "Distrust after" a date: certificates issued on that date are still trusted.
			r.DistrustAfter = t.Add(24*time.Hour - time.Second)
		}
		if e.SCTNotAfter != 0 {
			r.SCTNotAfter = time.Unix(e.SCTNotAfter, 0).UTC()
		}
		roots = append(roots, r)
	}
	s, err := pki.NewStore(name, src.Retrieved, true, roots)
	if err != nil {
		panic("refdata: " + err.Error())
	}
	return s
}

func loadStores() {
	storesOnce.Do(func() {
		mozilla = buildStore("Mozilla", mozillaSource, mozillaRoots)
		chrome = buildStore("Chrome", chromeSource, chromeRoots)
	})
}

// Stores returns the bundled root stores, Mozilla first. The values are shared
// and read-only.
func Stores() []*pki.Store {
	loadStores()
	return []*pki.Store{mozilla, chrome}
}

// RootName returns the CA owner and certificate name of a bundled root.
func RootName(sha string) (owner, name string, ok bool) {
	for _, list := range [][]rootEntry{mozillaRoots, chromeRoots} {
		for _, e := range list {
			if e.SHA256 == sha {
				return e.Owner, e.Name, true
			}
		}
	}
	return "", "", false
}

var (
	ctOnce  sync.Once
	ctByID  map[string]CTLog
	dhOnce  sync.Once
	dhBySHA map[string]DHPrime
)

// LookupCTLog finds a log by its 32-byte ID.
func LookupCTLog(id []byte) (CTLog, bool) {
	ctOnce.Do(func() {
		ctByID = make(map[string]CTLog, len(ctLogs))
		for _, l := range ctLogs {
			ctByID[l.ID] = l
		}
	})
	l, ok := ctByID[base64.StdEncoding.EncodeToString(id)]
	return l, ok
}

// LookupDHPrime finds a published group by the hex SHA-256 the prober records.
func LookupDHPrime(sha string) (DHPrime, bool) {
	dhOnce.Do(func() {
		dhBySHA = make(map[string]DHPrime, len(dhPrimes))
		for _, p := range dhPrimes {
			dhBySHA[p.SHA256] = p
		}
	})
	p, ok := dhBySHA[sha]
	return p, ok
}

// Sources lists every bundled list with its count, for the About page and the
// reference-data API.
func Sources() []Source {
	m, c, d, l, t := mozillaSource, chromeSource, dhSource, ctSource, lifetimeSource
	m.Count, c.Count, d.Count, l.Count, t.Count = len(mozillaRoots), len(chromeRoots), len(dhPrimes), len(ctLogs), len(lifetimeLimits)
	return []Source{m, c, l, d, t}
}
